import { Module } from '@nestjs/common';
import { ActivitiesService } from './activities.service';
import { ActivitiesController } from './activities.controller';
import { ActivityVoiceService } from './activity-voice.service';
import { NotificationsModule } from '../notifications/notifications.module';

// ActivityRecurrenceCron is intentionally NOT registered here. Recurring occurrences
// are generated by the main backend's cron against the shared database; running it
// in both services would create duplicate occurrences.
@Module({
  imports: [NotificationsModule],
  controllers: [ActivitiesController],
  providers: [ActivitiesService, ActivityVoiceService],
})
export class ActivitiesModule {}
